// ======= NAVBAR SCROLL SHADOW =======
const navbar = document.getElementById('navbar');
window.addEventListener('scroll', () => {
  if (window.scrollY > 20) {
    navbar.style.boxShadow = '0 4px 30px rgba(0,0,0,0.4)';
  } else {
    navbar.style.boxShadow = 'none';
  }
});

// ======= HAMBURGER MOBILE MENU =======
const hamburger = document.getElementById('hamburger');
const mobileMenu = document.getElementById('mobileMenu');
hamburger.addEventListener('click', () => {
  mobileMenu.classList.toggle('open');
});
function closeMobile() {
  mobileMenu.classList.remove('open');
}

// ======= SKILL BARS ANIMATE ON SCROLL =======
function animateSkills() {
  const fills = document.querySelectorAll('.sk-fill');
  fills.forEach(el => {
    const rect = el.closest('.skill-card').getBoundingClientRect();
    if (rect.top < window.innerHeight - 60) {
      el.style.width = el.dataset.w + '%';
    }
  });
}
window.addEventListener('scroll', animateSkills);
window.addEventListener('load', animateSkills);

// ======= FADE-IN SECTIONS ON SCROLL =======
const fadeEls = document.querySelectorAll(
  '.about-grid, .skills-grid, .projects-grid, .contact-grid, .section-title'
);
fadeEls.forEach(el => el.classList.add('fade-in'));

function checkFade() {
  fadeEls.forEach(el => {
    const rect = el.getBoundingClientRect();
    if (rect.top < window.innerHeight - 80) {
      el.classList.add('visible');
    }
  });
}
window.addEventListener('scroll', checkFade);
window.addEventListener('load', checkFade);

// ======= HERO ROLE ROTATOR =======
const roleRotator = document.getElementById('roleRotatorText');
const rotatingRoles = ['Frontend Developer', 'UI Designer', 'Freelancer'];

if (roleRotator && rotatingRoles.length) {
  let roleIndex = 0;
  let charIndex = 0;
  let isDeleting = false;

  const typeDelay = 90;
  const deleteDelay = 45;
  const holdDelay = 1100;

  function tick() {
    const currentRole = rotatingRoles[roleIndex];

    if (isDeleting) {
      charIndex = Math.max(0, charIndex - 1);
    } else {
      charIndex = Math.min(currentRole.length, charIndex + 1);
    }

    roleRotator.textContent = currentRole.slice(0, charIndex);

    let nextDelay = isDeleting ? deleteDelay : typeDelay;

    if (!isDeleting && charIndex === currentRole.length) {
      nextDelay = holdDelay;
      isDeleting = true;
    } else if (isDeleting && charIndex === 0) {
      isDeleting = false;
      roleIndex = (roleIndex + 1) % rotatingRoles.length;
      nextDelay = 350;
    }

    window.setTimeout(tick, nextDelay);
  }

  tick();
}

// ======= ACTIVE NAV LINK ON SCROLL =======
const sections = document.querySelectorAll('section[id]');
const navLinks = document.querySelectorAll('.nav-links a, .mobile-menu a');
window.addEventListener('scroll', () => {
  let current = '';
  sections.forEach(sec => {
    if (window.scrollY >= sec.offsetTop - 120) current = sec.id;
  });
  navLinks.forEach(a => {
    a.style.color = a.getAttribute('href') === '#' + current ? 'var(--accent)' : '';
  });
});

// ======= CONTACT FORM =======
const CONTACT_FORM = document.getElementById("contact-form");
const CONTACT_BUTTON = CONTACT_FORM?.querySelector(".form-submit");

if (CONTACT_FORM) {
  CONTACT_FORM.addEventListener("submit", function (e) {
    e.preventDefault();

    const name = document.getElementById("cName").value.trim();
    const email = document.getElementById("cEmail").value.trim();
    const message = document.getElementById("cMsg").value.trim();

    if (!name || !email || !message) {
      alert("Please fill in all fields!");
      return;
    }

    if (typeof emailjs === "undefined") {
      alert("Email service is not loaded yet. Please refresh the page and try again.");
      return;
    }

    const params = {
      name,
      email,
      message,
      time: new Date().toLocaleString()
    };

    if (CONTACT_BUTTON) {
      CONTACT_BUTTON.disabled = true;
      CONTACT_BUTTON.textContent = "Sending...";
    }

    emailjs.send("service_jkiq7ts", "template_gk7r0rz", params)
      .then(() => {
        alert("Message sent successfully!");
        CONTACT_FORM.reset();
      })
      .catch((err) => {
        const status = err?.status;
        const details = err?.text || err?.message || "Unknown error";
        console.log("EmailJS error:", err);

        if (status === 404) {
          alert("EmailJS 404: service/template ID is invalid or not created in your EmailJS dashboard.");
        } else {
          alert("Failed to send message. Check console for details.");
        }

        console.log("EmailJS details:", details);
      })
      .finally(() => {
        if (CONTACT_BUTTON) {
          CONTACT_BUTTON.disabled = false;
          CONTACT_BUTTON.textContent = "Send Message";
        }
      });
  });
}

// ======= SMOOTH SCROLL for all anchor links =======
document.querySelectorAll('a[href^="#"]').forEach(a => {
  a.addEventListener('click', e => {
    const target = document.querySelector(a.getAttribute('href'));
    if (target) {
      e.preventDefault();
      target.scrollIntoView({ behavior: 'smooth', block: 'start' });
    }
  });
});


